CREATE VIEW InsightsBI.vwADConcession_DEI_data AS 
select
CASE 
	WHEN apuk_concessiontypeid in ('00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000') 
		THEN 'Dual'
	WHEN apuk_concessiontypeid in ('00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000')
		THEN 'Retired'
	WHEN apuk_concessiontypeid in (
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000')
		THEN 'Other'
	WHEN apuk_concessiontypeid in ('00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000')
		THEN 'Unemployed'
	WHEN apuk_concessiontypeid in ('00000000-0000-0000-0000-000000000000', 
			'00000000-0000-0000-0000-000000000000')
		THEN 'Working Part Time'
	ELSE apuk_concessiontypeid_Name
	END AS CONCESSION_TYPE
,apuk_subscriptionyear
,apuk_sexualorientation
,apuk_genderidentity
,apuk_religionorbelief
,apuk_ethnicityother
,apuk_disabilities
,MemberGrade_Description
,Rics_PaymentMethod_Description
,AdjustedAge
,Rics_Ethnicity_Description
,GenderCode_Description
,Rics_Disability
,rics_localgroupidName
,apuk_regionid_name
,apuk_subregion_name
,apuk_worldregionid_name
,apuk_countryid_name
,apuk_concessionid
,ContactId
,C.Rics_contactno 
from [CE].[vwConcession] CON

LEFT JOIN CE.vwContact C
ON C.CONTACTID = CON.apuk_contactid

LEFT JOIN ce.vwLocalGroup LG
ON C.rics_localgroupid= lg.apuk_localgroupid

where apuk_subscriptionyear =2024
